const app=document.querySelector('.admin-app');const login=document.querySelector('.login-shell');document.querySelectorAll('[data-logout]').forEach(b=>b.addEventListener('click',()=>{app.classList.add('hidden');login.classList.add('active');document.querySelector('#email')?.focus()}));document.querySelector('[data-login]')?.addEventListener('submit',e=>{e.preventDefault();login.classList.remove('active');app.classList.remove('hidden');document.querySelector('main')?.focus()});document.querySelector('[data-password]')?.addEventListener('click',e=>{const input=document.querySelector('#senha');const visible=input.type==='text';input.type=visible?'password':'text';e.currentTarget.textContent=visible?'Mostrar':'Ocultar'});document.querySelectorAll('[data-toast]').forEach(b=>b.addEventListener('click',()=>{const t=document.querySelector('.toast');t.textContent=b.dataset.toast;t.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.hidden=true,2600)}));
